-- ClickUp Internal Team Clone: Production PostgreSQL Schema
-- Generated by replica-architect from replica/recon.md

-- Extensions
create extension if not exists "uuid-ossp";

-- 1. Users table
create table users (
  id uuid primary key default gen_random_uuid(),
  email text unique not null,
  password_hash text not null,
  full_name text not null,
  avatar_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- 2. Workspaces
create table workspaces (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text unique not null,
  owner_id uuid not null references users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_workspaces_owner on workspaces(owner_id);

-- 3. Workspace Members (Role-Based Access Control)
create type workspace_role as enum ('owner', 'admin', 'member', 'viewer');

create table workspace_members (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  role workspace_role not null default 'member',
  joined_at timestamptz not null default now(),
  constraint uq_workspace_member unique(workspace_id, user_id)
);
create index idx_workspace_members_user on workspace_members(user_id);
create index idx_workspace_members_workspace on workspace_members(workspace_id);

-- 4. Workspace Invites
create table workspace_invites (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  email text not null,
  role workspace_role not null default 'member',
  invited_by uuid not null references users(id) on delete cascade,
  token text unique not null,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index idx_workspace_invites_token on workspace_invites(token);

-- 5. Spaces (First level under Workspace: Engineering, Marketing, etc.)
create table spaces (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null,
  description text,
  icon text default 'folder',
  color text default '#7b68ee',
  is_private boolean not null default false,
  order_index integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_spaces_workspace on spaces(workspace_id);

-- 6. Space Members (Optional privacy overrides for private spaces)
create table space_members (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references spaces(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  constraint uq_space_member unique(space_id, user_id)
);

-- 7. Folders (Optional grouping inside Spaces)
create table folders (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references spaces(id) on delete cascade,
  name text not null,
  order_index integer not null default 0,
  is_private boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_folders_space on folders(space_id);

-- 8. Lists (Contains tasks; can belong directly to a Space or inside a Folder)
create table lists (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references spaces(id) on delete cascade,
  folder_id uuid references folders(id) on delete set null,
  name text not null,
  description text,
  order_index integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_lists_space on lists(space_id);
create index idx_lists_folder on lists(folder_id);

-- 9. Custom Statuses (Configurable per Space or List)
create type status_type as enum ('open', 'in_progress', 'review', 'done', 'closed');

create table statuses (
  id uuid primary key default gen_random_uuid(),
  space_id uuid references spaces(id) on delete cascade,
  list_id uuid references lists(id) on delete cascade,
  name text not null,
  color text not null default '#808080',
  type status_type not null default 'in_progress',
  order_index integer not null default 0,
  created_at timestamptz not null default now(),
  constraint chk_status_scope check (space_id is not null or list_id is not null)
);
create index idx_statuses_space on statuses(space_id);
create index idx_statuses_list on statuses(list_id);

-- 10. Tasks & Nested Subtasks
create type task_priority as enum ('urgent', 'high', 'normal', 'low', 'none');

create table tasks (
  id uuid primary key default gen_random_uuid(),
  list_id uuid not null references lists(id) on delete cascade,
  parent_task_id uuid references tasks(id) on delete cascade, -- enables nested subtasks
  title text not null,
  description text, -- rich text / markdown format
  status_id uuid not null references statuses(id) on delete restrict,
  priority task_priority not null default 'none',
  creator_id uuid not null references users(id) on delete restrict,
  start_date timestamptz,
  due_date timestamptz,
  time_estimate_minutes integer,
  time_spent_minutes integer not null default 0,
  order_index double precision not null default 1000.0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_tasks_list on tasks(list_id);
create index idx_tasks_parent on tasks(parent_task_id);
create index idx_tasks_status on tasks(status_id);
create index idx_tasks_due_date on tasks(due_date);
create index idx_tasks_creator on tasks(creator_id);

-- 11. Task Assignees (Multi-assignee support)
create table task_assignees (
  task_id uuid not null references tasks(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  assigned_at timestamptz not null default now(),
  primary key (task_id, user_id)
);
create index idx_task_assignees_user on task_assignees(user_id);

-- 12. Tags
create table tags (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  name text not null,
  color text not null default '#888888',
  created_at timestamptz not null default now(),
  constraint uq_workspace_tag unique(workspace_id, name)
);

create table task_tags (
  task_id uuid not null references tasks(id) on delete cascade,
  tag_id uuid not null references tags(id) on delete cascade,
  primary key (task_id, tag_id)
);

-- 13. Custom Fields (Flexible metadata without schema migrations)
create type custom_field_type as enum ('text', 'number', 'date', 'select', 'checkbox');

create table custom_field_definitions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  space_id uuid references spaces(id) on delete cascade,
  name text not null,
  field_type custom_field_type not null,
  config_json jsonb not null default '{}', -- select options, validation
  created_at timestamptz not null default now()
);

create table custom_field_values (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references tasks(id) on delete cascade,
  field_id uuid not null references custom_field_definitions(id) on delete cascade,
  value_json jsonb not null default 'null',
  updated_at timestamptz not null default now(),
  constraint uq_task_custom_field unique(task_id, field_id)
);

-- 14. Checklists & Checklist Items
create table task_checklists (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references tasks(id) on delete cascade,
  title text not null default 'Checklist',
  order_index integer not null default 0,
  created_at timestamptz not null default now()
);

create table task_checklist_items (
  id uuid primary key default gen_random_uuid(),
  checklist_id uuid not null references task_checklists(id) on delete cascade,
  title text not null,
  is_completed boolean not null default false,
  order_index integer not null default 0,
  created_at timestamptz not null default now()
);

-- 15. Task Comments & Activity Log
create table task_comments (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references tasks(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  content text not null,
  parent_comment_id uuid references task_comments(id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_task_comments_task on task_comments(task_id);

create table task_activity_logs (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references tasks(id) on delete cascade,
  user_id uuid not null references users(id) on delete set null,
  action_type text not null, -- 'created', 'status_changed', 'assigned', 'due_date_changed', etc.
  details_json jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create index idx_task_activity_task on task_activity_logs(task_id);

-- 16. Workspace Docs (Internal Wiki & SOPs)
create table docs (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspaces(id) on delete cascade,
  space_id uuid references spaces(id) on delete set null,
  title text not null default 'Untitled Doc',
  content text not null default '',
  created_by uuid not null references users(id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index idx_docs_workspace on docs(workspace_id);

-- 17. In-App Notifications
create table notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references users(id) on delete cascade,
  workspace_id uuid not null references workspaces(id) on delete cascade,
  entity_type text not null, -- 'task', 'comment', 'doc'
  entity_id uuid not null,
  message text not null,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);
create index idx_notifications_user_read on notifications(user_id, is_read);
